TITLE_AR = "ACRS (نظام الاستجابة الآلية للاختراق): احتواء الهجمات السيبرانية في الأنظمة بأقل إجراء كافٍ وآمن، مع تحقق على حاسوب كمّي"
TITLE_EN = "ACRS (Automated Compromise Response System): Safety-Gated Minimum-Action Cyberattack Containment, Validated on Quantum Hardware"
MAIN_CAT = "تصميم البرمجيات - Software Design"
SUB_CAT = "الأمن السيبراني (Cybersecurity)"

S1 = [
    "عندما يُكتشف هجوم سيبراني، تعزل أنظمة الاستجابة الآلية الجهاز المشتبه به عزلًا كاملًا، وفي الأنظمة الحيوية قد يوقف هذا العزل خدمات سليمة يعتمد عليها الناس. ففي هجوم WannaCry على النظام الصحي البريطاني تعطلت 46 جهة صحية لم تكن مصابة أصلًا [1].",
    "يقدّم هذا البحث نظام ACRS (Automated Compromise Response System)، الذي يصوغ قرار الاحتواء للشبكة كاملة كمسألة تحسين ثنائية (QUBO) تختار أقل إجراء يكفي لإيقاف الهجوم: عزل، أو تقييد، أو «تجزئة» للخادم الحرج تُبقي خدمته تعمل. ويمرّ كل قرار عبر بوابة سلامة مستقلة عن المحلّل تحيل القرارات الحرجة لموافقة شخصين بدل أن تفشل بصمت.",
    "سجّلنا معايير النجاح في Git قبل كل تجربة، واختبرنا على أكثر من 4,000 سيناريو هجوم لم يُصمَّم عليها النظام، وعلى جدار حماية Linux حقيقي، وعلى حواسيب IBM الكمّية. على 259 سلسلة هجوم احتوى ACRS تلقائيًا 97.7% مما يحتويه العزل الكامل الآمن (الحد المسجل مسبقًا 80%)، مع 0 خدمات متوقفة مقابل 292، ودون أي فشل صامت. وتأكدت النتيجة على بيانات جديدة تمامًا (0.980، و0.995 في شبكة صحية من 60 جهازًا)، وبنفس المحرّك دون تغيير أي وزن تحققت في شبكة بنك (0.902) وجامعة (0.839)، وكانت أقل بقليل في مصنع صناعي (0.792). ثم أعدنا تشغيل المحرّك على هجمات حقيقية موثقة في تقارير رسمية (WannaCry وNotPetya وHSE وColonial وChange Healthcare وغيرها: 16 لحظة اكتشاف، ثم 75 حادثة من مصادر مفتوحة 2013–2026) فكشفت أن المحلّل وحده لا يتفوق على قاعدة بسيطة؛ وبعد إضافة «أرضية أمان» مسجّلة مسبقًا (v12) صار الاحتواء التلقائي 100% و91%، والخدمات المتوقفة بعد الموافقات أقل من القاعدة والعزل الكامل، دائمًا بشرط وصول التنبيه. وطابق السلوك الحقيقي النموذج في 6,002 فحص، وقُطع المهاجم خلال 41 مللي ثانية (p95)، ولم تستطع التنبيهات المزوّرة إجبار النظام على إيقاف أي خدمة.",
    "وعلى العتاد الكمّي اكتشفنا أن عقوبة السلامة الكبيرة تخفي فروق التكلفة عن الدارة، فأثبتنا أن «أصغر عقوبة آمنة» تحافظ على الحل نفسه. بعدها حلّ حاسوب IBM قرار حادث في شبكة من أربعة مواقع (240 جهازًا): وجد الأمثل في 11 من 11 مسألة (75 كيوبت) على جهازين، وطابق القرار النهائي الحل الدقيق. ننشر الأهداف التي فشلت وكيف أصلحناها، ولا ندّعي تفوقًا كمّيًا. الشبكات اصطناعية، لكن النتائج تشير إلى أن الأنظمة يمكن أن تحتوي الهجوم دون أن توقف خدماتها.",
]

